import { Pipe, PipeTransform } from '@angular/core';
import { I18nService } from './i18n.service';

// Impure (pure: false) on purpose: the pipe's own input (the key string) never changes when
// the language toggles, only I18nService's internal signal does - a pure pipe wouldn't
// re-run and the UI would stay stuck in whichever language was active on first render.
@Pipe({ name: 'translate', standalone: true, pure: false })
export class TranslatePipe implements PipeTransform {
  constructor(private i18n: I18nService) {}

  transform(key: string): string {
    return this.i18n.t(key);
  }
}
